static void run() {
  try {
    throw new IllegalArgumentException("A");
  } finally {
    throw new IllegalStateException("B");
  }
}

class Base {
  int val = 10;
  int getVal() { return val; }
}
class Sub extends Base {
  int val = 20;
  @Override int getVal() { return val; }
}
public class Main {
  public static void main(String[] args) {
    Base b = new Sub();
    System.out.println(b.val + " " + b.getVal());
  }
}

static String fallback() {
  System.out.print("FB ");
  return "default";
}
public static void main(String[] args) {
  Optional<String> opt = Optional.of("HCL");
  System.out.print(opt.orElse(fallback()) + " ");
  System.out.print(opt.orElseGet(() -> fallback()));
}
